import{_ as n,o as a,c as i,ai as l}from"./chunks/framework.Ba-VnP44.js";const k=JSON.parse('{"title":"Agents · 智能体协作","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/01-foundation/agents.md","filePath":"ai/productivity/dev-spec/01-foundation/agents.md"}'),e={name:"ai/productivity/dev-spec/01-foundation/agents.md"};function p(t,s,r,h,c,b){return a(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="agents-·-智能体协作" tabindex="-1">Agents · 智能体协作 <a class="header-anchor" href="#agents-·-智能体协作" aria-label="Permalink to “Agents · 智能体协作”">​</a></h1><blockquote><p>第一层 · 能力底座。解决「谁来做什么、权限到哪」——明确执行者、审查者、规划者的边界，让多个 AI 角色协作时不互相覆盖、不自己宣布完成。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to “解决什么问题”">​</a></h2><ul><li>多开几个 AI 窗口同时改代码，结果互相覆盖。</li><li>AI 既当执行者又当验收人，自己说「做完了」就算通过。</li><li>派活只给一句话，各角色理解不一致。</li><li>需求还没定就拆并行角色，越拆越乱。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="什么时候需要多个-agent" tabindex="-1">什么时候需要多个 Agent <a class="header-anchor" href="#什么时候需要多个-agent" aria-label="Permalink to “什么时候需要多个 Agent”">​</a></h3><p>多 Agent 不是「多开几个窗口」，只有在任务能切成相对独立的块、每块有明确验收接口时才划算。</p><p><strong>适合拆分</strong>：</p><ul><li>前后端按冻结的契约并行。</li><li>彼此不冲突的模块改造。</li><li>一个执行、一个按清单审查。</li><li>检索、分析类任务并行收集信息。</li></ul><p><strong>不要拆</strong>：</p><ul><li>小任务、强耦合的改动。</li><li>需求还没冻结、上下文不足。</li><li>同一文件需要多人改。</li></ul><p>这时候多 Agent 只会放大沟通成本。</p><h3 id="三条硬边界" tabindex="-1">三条硬边界 <a class="header-anchor" href="#三条硬边界" aria-label="Permalink to “三条硬边界”">​</a></h3><ol><li><strong>文件所有权</strong>：每个 Agent 明确负责哪些文件、哪些只读，同一文件不同时改。共用文件先约定谁改。</li><li><strong>契约先冻结</strong>：接口、数据结构、字段名先定稿再并行；契约一变，所有人重读。</li><li><strong>审查者不判定通过</strong>：执行者、审查者、规划者分开；审查者只输出「问题清单和依据」，最终验收由人做，AI 之间不能互相宣布完成。</li></ol><h3 id="每个角色都要给齐上下文" tabindex="-1">每个角色都要给齐上下文 <a class="header-anchor" href="#每个角色都要给齐上下文" aria-label="Permalink to “每个角色都要给齐上下文”">​</a></h3><p>派给每个 Agent 的都要是同一份完整输入：<strong>任务 + 修改范围 + 不做项 + 验收标准</strong>，不接受「一句话派活」。</p><h3 id="角色模板" tabindex="-1">角色模板 <a class="header-anchor" href="#角色模板" aria-label="Permalink to “角色模板”">​</a></h3><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># &lt;角色名&gt;·&lt;任务短名&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 角色定位</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 职责：&lt;规划 / 执行 / 审查&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 权限：可改 &lt;文件清单&gt;；只读 &lt;文件清单&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不做：&lt;明确边界&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 共同上下文</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 任务：&lt;一句话&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 修改范围：&lt;允许改什么&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 禁止修改：&lt;不能碰什么&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 必须保持兼容：&lt;哪些不能变&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 验收标准：&lt;怎样算完成&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 交付物</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;这个角色要输出什么&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 完成判定</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 由人判定；本角色不宣布通过</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>多 Agent 分工（先出方案，不开始改）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个任务需要多 Agent 并行。请先给出分工方案，不要开始改代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：&lt;一句话&gt;</span></span>
<span class="line"><span>冻结的契约：&lt;接口/数据结构/字段名；若尚无，写「需先冻结」&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 按文件所有权划分，明确每个 Agent 负责哪些文件、哪些只读，确保同一文件不被同时改。</span></span>
<span class="line"><span>2. 如果契约尚未冻结，先只做契约设计，不要进入并行实现。</span></span>
<span class="line"><span>3. 每个 Agent 都收到同一份任务、修改范围、不做项和验收标准，不接受一句话派活。</span></span>
<span class="line"><span>4. 分工里包含执行者、审查者；审查者只输出问题清单和依据，不判定通过。</span></span>
<span class="line"><span>5. 说明结果如何收拢：各自 diff 越界检查、合并顺序、由谁做最终验收。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先输出分工表和风险点，等我确认后再启动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div></details><details><summary><strong>审查者角色（只报问题，不判通过）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你现在是审查者，只做审查，不修改任何文件，也不宣布通过。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>审查对象：&lt;改动描述 / diff&gt;</span></span>
<span class="line"><span>任务验收标准：&lt;粘贴&gt;</span></span>
<span class="line"><span>修改范围与不做项：&lt;粘贴&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按以下清单输出问题（每条给文件:行号和依据）：</span></span>
<span class="line"><span>1. 是否超出修改范围、触碰不做项。</span></span>
<span class="line"><span>2. 业务逻辑和边界条件（空值、越权、重复、并发）。</span></span>
<span class="line"><span>3. 异常处理与事务边界。</span></span>
<span class="line"><span>4. 接口、字段、数据兼容性。</span></span>
<span class="line"><span>5. 测试是否被放宽或删除。</span></span>
<span class="line"><span>6. 是否留下调试代码、遗留 TODO、无关格式化。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后输出「问题清单」和「需人确认的疑点」两部分。不要写「整体没问题，可以合并」这类判定结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 每个角色职责、权限、不做项写清，文件所有权无重叠。</li><li>[ ] 契约已冻结才并行；未冻结就先做契约设计。</li><li>[ ] 每个 Agent 都收到同一份完整输入，没有一句话派活。</li><li>[ ] 审查者只输出问题清单，没有自行宣布通过。</li><li>[ ] 结果收拢时做了 diff 越界检查，最终验收由人做。</li></ul><p>多 Agent 的收益来自「边界清晰」，不是「数量多」。边界没清之前，宁可单 Agent 顺序做。</p>`,24)])])}const g=n(e,[["render",p]]);export{k as __pageData,g as default};
